+fn mru_get<K: PartialEq, V: Clone>(memo: &mut Vec<(K, V)>, key: &K) -> Option<V> {
+    let i = memo.iter().position(|(k, _)| k == key)?;
+    let entry = memo.remove(i);
+    let val = entry.1.clone();
+    memo.push(entry);
+    Some(val)
