+          0\nENDSEC\n0\nEOF\n"
+    }
+
+    fn dxf_two() -> &'static [u8] {
+        b"0\nSECTION\n2\nHEADER\n9\n$INSUNITS\n70\n4\n0\nENDSEC\n0\nSECTION\n2\nENTITIES\n\
+          0\nLWPOLYLINE\n8\ncut\n90\n4\n70\n1\n10\n0\n20\n0\n10\n60\n20\n0\n10\n60\n20\n30\n10\n0\n20\n30\n\
+          0\nENDSEC\n0\nEOF\n"
